import{_ as e,o as i,c as o,aj as d}from"./chunks/framework.CvEpoKXn.js";const p=JSON.parse('{"title":"linux常用指令","description":"Linux 常用指令速查手册，涵盖文件操作、文本编辑、权限管理、进程管理、压缩归档与软件包管理，以 Ubuntu 为例","frontmatter":{"title":"linux常用指令","date":"2025-11-06T00:00:00.000Z","cover":"https://cdn.jsdelivr.net/gh/oyuovo/image@img/img/%E8%88%B0%E5%A8%98.jpg","description":"Linux 常用指令速查手册，涵盖文件操作、文本编辑、权限管理、进程管理、压缩归档与软件包管理，以 Ubuntu 为例","tags":["linux"],"categories":"开发工具"},"headers":[],"relativePath":"posts/linux.md","filePath":"posts/linux.md","lastUpdated":1788960575000}'),c={name:"posts/linux.md"};function a(t,l,r,u,n,s){return i(),o("div",null,[...l[0]||(l[0]=[d('<h2 id="ubuntu虚拟机联网教程" tabindex="-1">Ubuntu虚拟机联网教程 <a class="header-anchor" href="#ubuntu虚拟机联网教程" aria-label="Permalink to &quot;Ubuntu虚拟机联网教程&quot;">​</a></h2><p><a href="https://zhuanlan.zhihu.com/p/580910152" target="_blank" rel="noreferrer">VMware中Ubuntu联网方案（含泪试错版）</a></p><h1 id="常用linux指令-ubuntu为例" tabindex="-1">常用Linux指令-Ubuntu为例 <a class="header-anchor" href="#常用linux指令-ubuntu为例" aria-label="Permalink to &quot;常用Linux指令-Ubuntu为例&quot;">​</a></h1><blockquote><p>ctrl + alt + t 打开终端</p></blockquote><h2 id="文件和目录操作" tabindex="-1">文件和目录操作 <a class="header-anchor" href="#文件和目录操作" aria-label="Permalink to &quot;文件和目录操作&quot;">​</a></h2><ul><li>pwd：显示当前目录路径</li><li>ls：列出当前目录下的文件和文件夹 <ul><li>选项： <ul><li>-l：依次按照文件权限、链接数、所有者、所属组、文件大小、最后修改时间、文件名的顺序显示详细信息</li><li>-a：显示所有文件，包括隐藏文件</li></ul></li></ul></li><li>man <code>[要查的命令]</code>：查看命令的使用手册 <ul><li><code>[要查的命令]</code> --help：显示命令的帮助信息(效果类似man)</li></ul></li><li>clear：清屏</li></ul><blockquote><p>ctrl + l 也可以清屏</p></blockquote><ul><li>cd <code>[目录路径]</code>：切换当前工作目录到指定路径 <ul><li>cd ..：返回上一级目录</li><li>cd ~或者cd：切换到用户主目录</li><li>cd -：切换到上次所在目录</li></ul></li><li>mkdir <code>[目录名]</code>：创建新目录 <ul><li>-p：创建多级目录eg. mkdir -p dir1/dir2/dir3</li></ul></li><li>rmdir <code>[目录名]</code>：删除空目录</li><li>cp <code>[源文件路径]</code> <code>[目标文件路径]</code>：复制文件或目录 <ul><li>-r：递归复制整个目录及其内容</li></ul></li><li>rm <code>[文件路径]</code>：删除文件或目录 <ul><li>-r：递归删除目录及其内容</li><li>-f：强制删除，不提示确认</li></ul></li><li>mv <code>[源文件路径]</code> <code>[目标文件路径]</code>：移动或重命名文件或目录 <ul><li>mv oldname newname：重命名文件或目录</li><li>mv file.txt /path/to/destination/：移动文件到指定目录</li></ul></li><li>cat <code>[文件路径]</code>：显示文件内容 <ul><li>-n：显示行号</li></ul></li><li>tail <code>[文件路径]</code>：显示文件的最后几行 <ul><li>-n <code>[行数]</code>：指定显示的行数，默认显示最后10行</li><li>-f：实时跟踪文件内容的变化</li></ul><blockquote><p>crtl + c 停止跟踪</p></blockquote></li></ul><h2 id="文本编辑操作" tabindex="-1">文本编辑操作 <a class="header-anchor" href="#文本编辑操作" aria-label="Permalink to &quot;文本编辑操作&quot;">​</a></h2><h3 id="vim文本编辑器" tabindex="-1"><code>vim</code>文本编辑器 <a class="header-anchor" href="#vim文本编辑器" aria-label="Permalink to &quot;`vim`文本编辑器&quot;">​</a></h3><ol><li>工作模式</li></ol><ul><li><strong>普通模式(Normal Mode)</strong>：用于浏览和执行命令（默认模式）</li><li><strong>插入模式(Insert Mode)</strong>：用于编辑文本，按<code>i</code>或<code>a</code>或<code>o</code>进入插入模式，按<code>Esc</code>返回普通模式 <ul><li>i：在光标前插入</li><li>a：在光标后插入</li><li>o：在当前行下方新开一行插入</li></ul></li><li><strong>命令模式(Command Mode)</strong>：用于保存、退出等操作，按<code>:</code>或者<code>/</code>进入命令模式,按<code>Esc</code>返回普通模式</li><li><strong>可视模式(Visual Mode)</strong>：用于选择文本，按<code>v</code>进入可视模式，按<code>Esc</code>返回普通模式</li></ul><ol start="2"><li>常用命令</li></ol><ul><li>进入<code>vim</code>：在终端输入<code>vim [文件名]</code>，如果文件不存在则创建新文件</li><li>保存文件：在命令模式下输入<code>:w</code>，然后按<code>Enter</code></li><li>退出<code>vim</code>：在命令模式下输入<code>:q</code>，然后按<code>Enter</code></li><li>保存并退出：在命令模式下输入<code>:wq</code>，然后按<code>Enter</code></li><li>强制退出不保存：在命令模式下输入<code>:q!</code>，然后按<code>Enter</code></li></ul><h2 id="文件权限操作" tabindex="-1">文件权限操作 <a class="header-anchor" href="#文件权限操作" aria-label="Permalink to &quot;文件权限操作&quot;">​</a></h2><ul><li>Linux中每个文件都有三组权限：<strong>所有者(u)</strong>、<strong>所属组(g)</strong>、<strong>其他用户(o)</strong></li><li>每组包含三种权限：<strong>读(r=4)</strong>、<strong>写(w=2)</strong>、<strong>执行(x=1)</strong></li></ul><p>使用<code>ls -l</code>查看文件权限时，输出示例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-rwxr-xr-- 1 user group 1024 Mar 23 10:00 file.txt</span></span></code></pre></div><p>第一位<code>-</code>表示普通文件（<code>d</code>为目录），后面每三位一组分别对应所有者、所属组、其他用户的权限</p><ul><li>chmod <code>[权限]</code> <code>[文件路径]</code>：修改文件权限 <ul><li>数字方式：<code>chmod 755 file.txt</code>（所有者rwx=7，组r-x=5，其他r-x=5）</li><li>符号方式：<code>chmod u+x file.txt</code>（给所有者添加执行权限）</li><li>常见组合： <ul><li><code>chmod 777</code>：所有用户可读可写可执行</li><li><code>chmod 644</code>：所有者可读写，其他用户只读</li><li><code>chmod +x script.sh</code>：给所有用户添加执行权限</li></ul></li><li>-R：递归修改目录及其内容的权限</li></ul></li><li>chown <code>[用户:组]</code> <code>[文件路径]</code>：修改文件的所有者和所属组 <ul><li><code>chown user file.txt</code>：修改所有者</li><li><code>chown user:group file.txt</code>：同时修改所有者和所属组</li><li><code>chown :group file.txt</code>：只修改所属组</li><li>-R：递归修改目录及其内容的所有者</li></ul></li><li>chgrp <code>[组名]</code> <code>[文件路径]</code>：修改文件的所属组 <ul><li>-R：递归修改</li></ul></li></ul><h2 id="进程管理相关" tabindex="-1">进程管理相关 <a class="header-anchor" href="#进程管理相关" aria-label="Permalink to &quot;进程管理相关&quot;">​</a></h2><ul><li>ps：查看当前运行的进程 <ul><li>ps aux：查看系统中所有进程的详细信息</li><li>ps -ef：以全格式显示所有进程（包含父进程ID）</li></ul></li><li>top：实时动态查看系统进程和资源使用情况 <blockquote><p>按<code>q</code>退出，按<code>M</code>按内存排序，按<code>P</code>按CPU排序</p></blockquote></li><li>kill <code>[进程PID]</code>：终止指定进程 <ul><li>kill -9 <code>[PID]</code>：强制终止进程</li><li>kill -15 <code>[PID]</code>：正常终止进程（默认信号）</li></ul></li><li>killall <code>[进程名]</code>：按名称终止所有同名进程</li><li>jobs：查看当前终端的后台任务</li><li>bg <code>[任务号]</code>：将暂停的任务放到后台继续运行</li><li>fg <code>[任务号]</code>：将后台任务调到前台运行 <blockquote><p>运行命令时在末尾加<code>&amp;</code>可以直接将任务放到后台运行，如<code>./script.sh &amp;</code></p></blockquote></li><li>nohup <code>[命令]</code> &amp;：使命令在后台运行，且不受终端关闭影响</li><li>systemctl <code>[操作]</code> <code>[服务名]</code>：管理系统服务 <ul><li><code>systemctl start nginx</code>：启动服务</li><li><code>systemctl stop nginx</code>：停止服务</li><li><code>systemctl restart nginx</code>：重启服务</li><li><code>systemctl status nginx</code>：查看服务状态</li><li><code>systemctl enable nginx</code>：设置开机自启</li><li><code>systemctl disable nginx</code>：取消开机自启</li></ul></li></ul><h2 id="压缩归档相关" tabindex="-1">压缩归档相关 <a class="header-anchor" href="#压缩归档相关" aria-label="Permalink to &quot;压缩归档相关&quot;">​</a></h2><h3 id="tar命令" tabindex="-1">tar命令 <a class="header-anchor" href="#tar命令" aria-label="Permalink to &quot;tar命令&quot;">​</a></h3><ul><li>tar：用于打包和解包文件（常与压缩工具配合使用） <ul><li>常用选项： <ul><li>-c：创建归档文件</li><li>-x：解包归档文件</li><li>-v：显示操作过程</li><li>-f：指定归档文件名（必须放在选项最后）</li><li>-z：使用gzip压缩/解压（.tar.gz 或 .tgz）</li><li>-j：使用bzip2压缩/解压（.tar.bz2）</li></ul></li><li>常用组合： <ul><li><code>tar -czvf archive.tar.gz dir/</code>：将目录压缩为.tar.gz</li><li><code>tar -xzvf archive.tar.gz</code>：解压.tar.gz文件</li><li><code>tar -xzvf archive.tar.gz -C /target/path/</code>：解压到指定目录</li><li><code>tar -cjvf archive.tar.bz2 dir/</code>：将目录压缩为.tar.bz2</li><li><code>tar -xjvf archive.tar.bz2</code>：解压.tar.bz2文件</li></ul></li></ul></li></ul><h3 id="zip-unzip命令" tabindex="-1">zip/unzip命令 <a class="header-anchor" href="#zip-unzip命令" aria-label="Permalink to &quot;zip/unzip命令&quot;">​</a></h3><ul><li>zip <code>[压缩文件名.zip]</code> <code>[文件...]</code>：压缩文件为.zip格式 <ul><li>-r：递归压缩目录，如<code>zip -r archive.zip dir/</code></li></ul></li><li>unzip <code>[压缩文件名.zip]</code>：解压.zip文件 <ul><li>-d <code>[目标路径]</code>：解压到指定目录，如<code>unzip archive.zip -d /target/path/</code></li><li>-l：查看压缩包内容但不解压</li></ul></li></ul><h2 id="安装软件相关" tabindex="-1">安装软件相关 <a class="header-anchor" href="#安装软件相关" aria-label="Permalink to &quot;安装软件相关&quot;">​</a></h2><h3 id="apt安装" tabindex="-1">apt安装 <a class="header-anchor" href="#apt安装" aria-label="Permalink to &quot;apt安装&quot;">​</a></h3><ul><li>更新软件包列表：<code>sudo apt update</code></li><li>升级已安装的软件包：<code>sudo apt upgrade</code></li><li>安装软件包：<code>sudo apt install [软件包名]</code></li><li>删除软件包：<code>sudo apt remove [软件包名]</code></li><li>搜索软件包：<code>apt search [关键词]</code></li><li>显示已安装的软件包信息：<code>apt show [软件包名]</code></li></ul><h3 id="deb安装" tabindex="-1">deb安装 <a class="header-anchor" href="#deb安装" aria-label="Permalink to &quot;deb安装&quot;">​</a></h3><ul><li>使用<code>dpkg</code>安装<code>.deb</code>包：<code>sudo dpkg -i [包名.deb]</code></li><li>修复依赖关系：<code>sudo apt -f install</code></li><li>卸载<code>.deb</code>包：<code>sudo dpkg -r [包名]</code></li></ul><h1 id="其他补充" tabindex="-1">其他补充 <a class="header-anchor" href="#其他补充" aria-label="Permalink to &quot;其他补充&quot;">​</a></h1><ul><li>使用<code>hostname -I</code>查询ip地址</li></ul>',34)])])}const b=e(c,[["render",a]]);export{p as __pageData,b as default};
